// Parse incident payload and extract IOC list
const item = $input.first().json.body;
const incidentId = item.id || 'INC-UNKNOWN';
const severity = item.severity || 'MEDIUM';
const iocs = item.iocs || [];

return [{
  json: {
    incidentId,
    title: item.title,
    severity,
    iocsCount: iocs.length,
    iocs,
    processedAt: new Date().toISOString()
  }
}];

// Mock AI Triage analysis and threat intelligence enrichment
const incident = $input.first().json;

const enrichedMitigations = [
  'Verify host containment status via EDR',
  'Enforce immediate password reset and MFA re-authentication',
  'Check lateral connection logs for preceding 2 hours'
];

return [{
  json: {
    success: true,
    incidentId: incident.incidentId,
    status: 'TRIAGED',
    aiAnalysis: {
      summary: `Automated n8n triage completed for incident ${incident.incidentId}. AI confirmed high risk pattern.`,
      confidenceScore: 0.93,
      recommendedMitigations: enrichedMitigations,
      analyzedAt: new Date().toISOString()
    }
  }
}];
